apiVersion: apps/v1
kind: Deployment
metadata: {name: vuoro-web, namespace: vuoro-system}
spec:
  replicas: 1
  selector:
    matchLabels: {app.kubernetes.io/name: vuoro-web}
  template:
    metadata:
      labels: {app.kubernetes.io/name: vuoro-web}
      annotations:
        checksum/vuoro-web-site: 9cd3d9be6d510311b20508a2b8fcea3425888db83d6463e0d4c8c56aa8da6a29
    spec:
      automountServiceAccountToken: false
      securityContext: {runAsNonRoot: true, runAsUser: 65532, runAsGroup: 65532, fsGroup: 65532, seccompProfile: {type: RuntimeDefault}}
      containers:
        - name: web
          image: cgr.dev/chainguard/nginx@sha256:2189489ef3fa5b1e94a8463f98f9c148a4d8e7498d3f747069fc78de405742fc
          ports: [{name: http, containerPort: 8080}]
          volumeMounts:
            - {name: site, mountPath: /usr/share/nginx/html, readOnly: true}
            - {name: site, mountPath: /etc/nginx/conf.d/default.conf, subPath: default.conf, readOnly: true}
            - {name: nginx-tmp, mountPath: /var/lib/nginx/tmp}
            - {name: nginx-run, mountPath: /var/run}
          resources: {requests: {cpu: 20m, memory: 32Mi}, limits: {cpu: 100m, memory: 96Mi}}
          securityContext: {allowPrivilegeEscalation: false, readOnlyRootFilesystem: true, capabilities: {drop: [ALL]}}
      volumes:
        - name: site
          projected:
            sources:
              - configMap: {name: vuoro-web-site}
              - configMap: {name: vuoro-web-landing}
        - {name: nginx-tmp, emptyDir: {sizeLimit: 32Mi}}
        - {name: nginx-run, emptyDir: {sizeLimit: 4Mi}}
---
apiVersion: v1
kind: Service
metadata: {name: vuoro-web, namespace: vuoro-system}
spec:
  selector: {app.kubernetes.io/name: vuoro-web}
  ports: [{name: http, port: 8080, targetPort: http}]
---
apiVersion: v1
kind: ConfigMap
metadata: {name: vuoro-web-site, namespace: vuoro-system}
data:
  default.conf: |
    # Raw network origin belongs only in short-retention security logs. Query
    # strings, cookies, authorization and request bodies are deliberately
    # excluded. Product analytics remains separately consent/privacy bounded.
    log_format vuoro_security escape=json '{"time":"$time_iso8601","source_ip":"$http_cf_connecting_ip","method":"$request_method","host":"$host","uri":"$uri","status":$status,"bytes":$body_bytes_sent,"cf_ray":"$http_cf_ray"}';
    server {
      listen 8080;
      server_name _;
      # Cloudflared terminates TLS. Relative redirects preserve the client's
      # external HTTPS origin without exposing this internal listener port.
      absolute_redirect off;
      root /usr/share/nginx/html;
      access_log /dev/stdout vuoro_security;
      add_header Content-Security-Policy "default-src 'self'; connect-src https://api.vuoro.cloud; img-src 'self' data:; script-src 'self'; style-src 'self'; base-uri 'none'; frame-ancestors 'none'" always;
      add_header Referrer-Policy "no-referrer" always;
      add_header X-Content-Type-Options "nosniff" always;
      location = / { try_files /landing.html =404; }
      location = /mental-model { return 308 /mental-model.html; }
      location = /architecture { return 308 /architecture.html; }
      location = /ecosystem { return 308 /ecosystem.html; }
      location = /alternatives { return 308 /alternatives.html; }
      location = /showcase { return 308 /showcase.html; }
      location ~ ^/(mental-model|architecture|ecosystem|alternatives|showcase)\.html$ { try_files $uri =404; }
      location = /docs.css { try_files $uri =404; }
      location = /app.css { try_files $uri =404; }
      location = /app.js { try_files $uri =404; }
      location = /landing.js { try_files $uri =404; }
      location = /landing.css { try_files $uri =404; }
      location = /showcase.css { try_files $uri =404; }
      location = /showcase.js { try_files $uri =404; }
      location = /takeover.js { try_files $uri =404; }
      location ~ ^/(join|dashboard|activate|admin)$ { try_files /index.html =404; }
      location / { return 404; }
    }
  index.html: |
    <!doctype html>
    <html lang="en">
    <meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Vuoro application shell for authenticated and operator routes."><link rel="stylesheet" href="/app.css"><script src="/app.js" defer></script>
    <title>Vuoro application</title>
    <header><a class="brand" href="/">Vuoro</a><nav><a href="/">Public overview</a></nav></header>
    <main id="app">
      <section class="hero"><p class="eyebrow">Coordination for work that runs elsewhere</p><h1>Put more work in motion without keeping all of it in your head.</h1><p class="lede">Vuoro keeps one current view of what's ready, who has it, what finished, and what needs attention — across every agent, session, and machine you run. It doesn't run any of them.</p><p class="boundary">Coordinate the work. Keep control of where it runs.</p><div class="actions"><a class="button" href="#local">Try Vuoro locally</a><a class="secondary" href="#modes">See why it exists</a></div></section>
      <section id="modes" class="modes"><p class="eyebrow">Use the simplest mode that solves your problem.</p><h2>The source of truth outgrew the machine.</h2><div class="mode-ladder"><article><p class="mode-name">One machine</p><h3>Local state is enough.</h3><p>Keep it simple.</p></article><p class="transition">work spans concurrent sessions <span aria-hidden="true">↓</span></p><article><p class="mode-name">Shared state</p><h3>Everyone needs the same current answer.</h3></article><p class="transition">work spans machines and time <span aria-hidden="true">↓</span></p><article><p class="mode-name">Served</p><h3>Coordination no longer depends on one workstation being present.</h3></article><p class="transition">you don't want to operate that service <span aria-hidden="true">↓</span></p><article><p class="mode-name">Vuoro Cloud</p><h3>The same coordination boundary, operated for you.</h3></article></div></section>
      <section id="local"><p class="eyebrow">Start with the operational thread</p><h2>See work become actionable.</h2><p class="section-lede">The local quickstart is designed to prove one thing: you can follow work from definition to readiness, ownership, outcome, and the next actionable step without reconstructing the story from several sessions.</p><ol class="thread"><li><span>1</span><strong>Initialize</strong><small>Keep coordination state on this machine.</small></li><li><span>2</span><strong>Identify work</strong><small>Describe the work and its dependencies.</small></li><li><span>3</span><strong>See what's ready</strong><small>Get the current answer, not a stale plan.</small></li><li><span>4</span><strong>Claim it</strong><small>Make ownership visible to other sessions.</small></li><li><span>5</span><strong>Record the outcome</strong><small>See what becomes actionable next.</small></li></ol><div class="release-note"><p><strong>The immutable local quickstart is not published yet.</strong> We won't show an install command that cannot run. Local use will be the primary no-invitation path as soon as the tested CLI releases are available.</p><p>That's Vuoro locally. When several sessions or machines need the same view, move the coordination state to served mode. Your workflow doesn't need to become a hosted agent runtime.</p></div></section>
      <section id="operations"><p class="eyebrow">Built for operations, not just demos</p><h2>The contracts matter more than the feature list.</h2><div class="contract-grid"><article><h3>Compatibility</h3><p>Tested client, server, adapter, and schema versions are published together. Unsupported skew fails at the boundary rather than guessing.</p></article><article><h3>Migration</h3><p>Shared state has an explicit migration owner, ordered lifecycle, failure state, and recovery path.</p></article><article><h3>Failure semantics</h3><p>Claims, leases, retries, contention, and outcome reporting remain explicit when workers disappear or networks divide.</p></article><article><h3>Authority boundaries</h3><p>Readiness, execution lifecycle, knowledge, audit judgment, and output evidence retain separate owners.</p></article><article><h3>Portability</h3><p>The coordination boundary stays recognizable across local, self-hosted served, and Vuoro Cloud modes.</p></article><article><h3>Recovery</h3><p>Durable state, reconstructable state, backup evidence, and degraded operation are documented separately.</p></article></div></section>
      <section id="cloud" class="cloud"><p class="eyebrow">Hosted coordination</p><h2>Your machine isn't enough anymore. We can operate the shared state.</h2><p class="section-lede">Vuoro Cloud is the invitation-only hosted service. It provides repository-scoped coordination while your code, workers, credentials, execution environments, and artifact storage stay under your control.</p><div class="grid"><article><h3>Coordinate centrally</h3><p>Plans, claims, outcomes, knowledge, and evidence stay current across machines and time.</p></article><article><h3>Execute where you choose</h3><p>User-operated workers and connectors retain machine-local effects and secrets. Vuoro Cloud does not run arbitrary code.</p></article><article><h3>Carry evidence, not custody</h3><p>User-owned storage keeps artifacts. Vuoro records bounded observations and immutable references, never S3 credentials.</p></article></div><p class="notice"><strong>Alpha:</strong> interfaces, availability, retention, migration, and recovery commitments may change. Do not use this PoC for regulated, safety-critical, or production-only workloads.</p></section>
      <section id="invite"><h2>Request a Vuoro Cloud invitation</h2><p>Trying Vuoro locally will not require an invitation. This form is only for the hosted alpha. Tell us what shared or served coordination you want to test; submission is not a promise of access or service availability.</p><form id="invite-form"><label>Email <input type="email" name="email" required autocomplete="email"></label><label>Name <input name="name" maxlength="120" autocomplete="name"></label><label>Organization or project <input name="organization" maxlength="160" autocomplete="organization"></label><label>What would you test? <textarea name="use_case" minlength="20" maxlength="2000" required></textarea></label><label class="trap">Website <input name="website" tabindex="-1" autocomplete="off"></label><label class="consent"><input type="checkbox" name="consent" required> I agree that Vuoro may retain this request and contact me about alpha access. See the privacy notice below.</label><button>Request hosted alpha access</button></form><div id="form-message" aria-live="polite"></div></section>
      <section id="faq"><h2>Common questions</h2><details><summary>Does Vuoro run arbitrary code?</summary><p>No. Vuoro coordinates released operations. Execution remains with constrained, user-operated workers and connectors.</p></details><details><summary>Does local Vuoro require a Cloud account?</summary><p>No. Local mode keeps its coordination state on your machine. Vuoro Cloud invitations apply only to the hosted service.</p></details><details><summary>Does Vuoro receive repository or S3 credentials?</summary><p>No. Repository credentials stay with your tooling, and S3 support records external receipts rather than credentials or objects.</p></details><details><summary>Is Vuoro Cloud production ready?</summary><p>No. It is an invitation-only alpha PoC. Availability, support, migration, recovery, and compatibility claims are not yet production commitments.</p></details><details><summary>Can I self-host served mode?</summary><p>The source and declarative composition support that direction. Production-quality self-hosting guidance will follow the public onboarding proof.</p></details><details><summary>How is hosted access controlled?</summary><p>Admission requires GitHub OAuth and a supplemental single-use invitation. Browser sessions and API credentials are revocable and workspace scoped.</p></details></section>
      <section id="contact"><h2>Contact</h2><p>Questions, security coordination, or partnership enquiries: <a data-event="contact_clicked" href="mailto:contact%40kotona.app">contact&#64;kotona.app</a>.</p></section>
      <section class="legal"><h2>Alpha and privacy notice</h2><p>Vuoro Cloud is provided for evaluation without uptime, durability, support, or fitness guarantees. Do not submit secrets or sensitive customer data through the request form. We retain the contact details and use-case text you submit for alpha review. First-party analytics record bounded page paths, coarse device class, and rotating keyed network/visitor identifiers for aggregate usage and abuse detection; no advertising trackers or raw IP addresses are stored. Global Privacy Control and Do Not Track suppress page events. Contact <a href="mailto:contact%40kotona.app">contact&#64;kotona.app</a> for access or deletion requests.</p></section>
    </main><footer>Vuoro · coordinate the work, keep control of where it runs · <a href="mailto:contact%40kotona.app">contact&#64;kotona.app</a></footer>
  app.css: |
    :root{color-scheme:light;--ink:#14211d;--muted:#52625c;--paper:#f7f5ee;--card:#fffdf7;--line:#d9d7cb;--accent:#176b52;--soft:#e7efe9}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}header,main,footer{max-width:72rem;margin:auto;padding:1.2rem 2rem}header{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}nav{display:flex;gap:1rem;flex-wrap:wrap}.brand{font-weight:800;text-decoration:none}.brand span,.eyebrow,.mode-name{color:var(--accent)}a{color:#075c7a}.hero{padding:7rem 0 5rem}.hero h1{font-size:clamp(2.7rem,7vw,5.8rem);line-height:.98;max-width:15ch;margin:.25rem 0 1.5rem}.lede,.section-lede{font-size:1.25rem;max-width:48rem;color:var(--muted)}.boundary{font-size:1.15rem;font-weight:750}section{padding:3.5rem 0;scroll-margin-top:1rem}h2{font-size:clamp(2rem,4vw,3.5rem);line-height:1.08;max-width:19ch;margin:.35rem 0 1.4rem}h3{line-height:1.25}.eyebrow,.mode-name{text-transform:uppercase;letter-spacing:.09em;font-size:.8rem;font-weight:800}.grid,.contract-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));gap:1rem}.grid article,.contract-grid article,.notice,.legal,.release-note{background:var(--card);border:1px solid var(--line);padding:1.3rem;border-radius:.8rem}.contract-grid article{border-top:3px solid var(--accent)}.actions{display:flex;gap:1rem;flex-wrap:wrap;margin:2rem 0}.button,button{background:var(--accent);color:white;border:0;border-radius:.4rem;padding:.8rem 1.1rem;text-decoration:none;font-weight:700}.secondary{padding:.8rem 0}.modes,.cloud{border-top:1px solid var(--line)}.mode-ladder{max-width:56rem}.mode-ladder article{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--accent);padding:1rem 1.4rem}.mode-ladder article h3,.mode-ladder article p{margin:.25rem 0}.transition{color:var(--muted);font-size:.9rem;margin:.7rem 0 .7rem 1.5rem}.transition span{display:block;color:var(--accent);font-size:1.4rem;line-height:1}.thread{list-style:none;display:grid;grid-template-columns:repeat(5,1fr);max-width:none;padding:0;margin:2rem 0;gap:.5rem}.thread li{position:relative;background:var(--soft);padding:1rem;border-radius:.6rem}.thread span{display:block;color:var(--accent);font-weight:800}.thread strong,.thread small{display:block}.thread small{color:var(--muted);margin-top:.4rem}.release-note{max-width:52rem}form{display:grid;gap:.9rem;max-width:42rem}label{display:grid;gap:.3rem}input,textarea,button,select{font:inherit;padding:.7rem}textarea{min-height:9rem}.consent{grid-template-columns:auto 1fr}.trap{position:absolute;left:-10000px}button{cursor:pointer;width:max-content}details{border-top:1px solid var(--line);padding:1rem 0}summary{font-weight:700;cursor:pointer}.error{color:#9b1c1c}.ok{color:#176b35}footer{border-top:1px solid var(--line);color:var(--muted);margin-top:3rem}@media(max-width:60rem){.thread{grid-template-columns:1fr 1fr}}@media(max-width:48rem){header{align-items:flex-start;gap:1rem;flex-direction:column}.hero{padding-top:4rem}.thread{grid-template-columns:1fr}nav{font-size:.9rem}}
    #workspaces{display:grid;gap:1.2rem;margin:1.3rem 0}.workspace-card{background:var(--card);border:1px solid var(--line);border-left:4px solid var(--accent);border-radius:.5rem;padding:1.2rem 1.4rem}.workspace-card.pending-change{border-left-color:#8b5316}.workspace-card.needs-attention{border-left-color:#9b1c1c}.workspace-card h3{margin:.1rem 0 .3rem}.workspace-state{font-weight:750;margin:.2rem 0}.workspace-facts{display:flex;gap:.4rem 1.2rem;flex-wrap:wrap;margin:.6rem 0;color:var(--muted);font-size:.9rem}.workspace-facts span{min-width:10rem}.workspace-guidance{max-width:68ch;margin:.6rem 0}.workspace-guidance.attention{color:#824a12}.workspace-local{border-top:1px solid var(--line);padding-top:.7rem;color:var(--muted);font-size:.9rem;max-width:72ch}.workspace-connect{border-top:1px solid var(--line);margin-top:1.2rem;padding:1rem 0 0}.workspace-connect h4{font-size:1.12rem;margin:.1rem 0 .45rem}.workspace-connect code{overflow-wrap:anywhere}.workspace-connect details{max-width:50rem}.workspace-connect summary{cursor:pointer}.workspace-connect ol{margin:.6rem 0;padding-left:1.4rem}.workspace-connect li{margin:.35rem 0}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid #075c7a;outline-offset:3px}
  app.js: |
    const API = "https://api.vuoro.cloud";
    const app = document.querySelector("#app");
    const csrf = () => document.cookie.split("; ").find(v => v.startsWith("vuoro_csrf="))?.split("=")[1] || "";
    async function call(path, options = {}) {
      options.credentials = "include";
      options.headers = {"Content-Type":"application/json", ...(options.headers || {})};
      if (options.method && options.method !== "GET") options.headers["X-CSRF-Token"] = csrf();
      const response = await fetch(API + path, options);
      const body = response.status === 204 ? null : await response.json();
      if (!response.ok) { const error = new Error(body?.error?.message || `Request failed (${response.status})`); error.status = response.status; throw error; }
      return body;
    }
    function message(text, kind = "") { const p=document.createElement("p"); p.className=kind; p.textContent=text; app.append(p); }
    const knownPath=()=>["/","/join","/dashboard","/activate","/bootstrap","/self-host","/faq","/contact"].includes(location.pathname)?location.pathname:"/";
    const visitor=()=>{let value=sessionStorage.getItem("vuoro_visitor");if(!value){value=crypto.randomUUID().replaceAll("-","");sessionStorage.setItem("vuoro_visitor",value)}return value};
    const referrer=()=>{if(!document.referrer)return"direct";const host=new URL(document.referrer).hostname;if(host.includes("google")||host.includes("bing")||host.includes("duckduckgo"))return"search";if(host==="github.com")return"github";return"other"};
    async function track(event_name,path=knownPath()){if(navigator.doNotTrack==="1"||navigator.globalPrivacyControl)return;try{await call("/api/control/v1/public/events",{method:"POST",body:JSON.stringify({event_name,path,referrer_class:referrer(),visitor_id:visitor()})})}catch(_){}}
    async function join() {
      const signedIn = sessionStorage.getItem("vuoro_join_signin_started");
      if (!signedIn) {
        app.innerHTML = `<section><h2>Join the alpha</h2><p><a id="github-signin" href="${API}/api/control/v1/auth/github/start?redirect_path=/join">Sign in with GitHub</a> to continue.</p></section>`;
        document.querySelector("#github-signin").onclick = () => sessionStorage.setItem("vuoro_join_signin_started", "1");
        return;
      }
      app.innerHTML = `<section><h2>Join the alpha</h2><p>Checking your account…</p></section>`;
      try {
        await call("/api/control/v1/workspaces");
        sessionStorage.removeItem("vuoro_join_signin_started");
        location.href = "/dashboard";
        return;
      } catch (error) {
        if (error.status !== 401 && error.status !== 403) { message(error.message, "error"); return; }
      }
      app.innerHTML = `<section><h2>Join the alpha</h2><p>Signed in with GitHub. Enter your invitation code to redeem it.</p><form id="join"><label>Invitation <input name="invitation" required autocomplete="off"></label><button>Redeem</button></form><p><a id="github-resignin" href="${API}/api/control/v1/auth/github/start?redirect_path=/join">Sign in again</a></p></section>`;
      document.querySelector("#join").onsubmit = async event => { event.preventDefault(); try { await call("/api/control/v1/invitations/redeem", {method:"POST",body:JSON.stringify({invitation:new FormData(event.target).get("invitation")})}); sessionStorage.removeItem("vuoro_join_signin_started"); location.href="/dashboard"; } catch(error) { message(error.message,"error"); } };
    }
    const PROVISIONING_STEPS = ["REQUESTED","PROVISIONING_DATABASE","MIGRATING","DEPLOYING_RUNTIME","VERIFYING","READY"];
    const TERMINAL_STATES = new Set(["READY","FAILED_TERMINAL","SUSPENDED","DELETED","RETAINED"]);
    const STATE_NAMES = {REQUESTED:"Requested",PROVISIONING_DATABASE:"Creating database",MIGRATING:"Migrating data",DEPLOYING_RUNTIME:"Deploying runtime",VERIFYING:"Checking runtime",READY:"Ready",DEGRADED:"Needs a repository",FAILED_RETRYABLE:"Retrying after a provisioning failure",FAILED_TERMINAL:"Provisioning stopped",ROLLBACK_REQUIRED:"Migration repair required",SUSPENDED:"Suspended",DELETION_REQUESTED:"Deletion requested",RETAINED:"Retained",DELETED:"Deleted"};
    const BLOCKERS = {"repository-required":"Bind one repository to start the runtime.","migration-failed":"The migration failed. Contact the Vuoro operator for repair before retrying.","tenant-resource-collision":"A tenant resource conflicts with another resource. Contact the Vuoro operator.","reconcile-failed":"Provisioning failed and will retry. If it stays here, contact the Vuoro operator.","tenant-migration-required":"The current runtime is retained. Contact the Vuoro operator for an explicit tenant migration.","tenant-schema-unknown":"The current runtime is retained. Contact the Vuoro operator to diagnose the tenant schema.","tenant-migration-active":"An explicit tenant migration is active. Wait for the operator to finish it.",other:"Provisioning needs attention. Contact the Vuoro operator."};
    const CLIENT_STEPS = {
      "claude-connector": {name:"Claude",steps:["Open the Vuoro custom connector your Claude owner has made available. Ask that owner if it is missing.","Connect with GitHub, then select this workspace on the Vuoro consent page.","Try list_ready_work. If an earlier grant lacks a new scope or points to another workspace, disconnect the connector in Claude, then connect it again to start fresh consent."]},
      "chatgpt-connector": {name:"ChatGPT",steps:["Open the Vuoro custom MCP app already configured in your ChatGPT workspace. A workspace admin or authorized developer must create it first.","Connect with GitHub, then select this workspace on the Vuoro consent page.","Try list_ready_work. If tools or scopes are missing, ask your ChatGPT workspace administrator to check the app and start a new authorization; an old grant does not widen on refresh."]}
    };
    const paragraph=(content,className="")=>{const element=document.createElement("p");element.className=className;element.textContent=content;return element};
    const readableTime=value=>{const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString():"not observed"};
    const stateLabel=state=>STATE_NAMES[state]||"State unknown";
    const currentGeneration=value=>Number.isInteger(value.generation)&&Number.isInteger(value.observed_generation)&&value.observed_generation>=value.generation;
    function addConnection(card,value,mcp){
      if(value.state!=="READY")return;
      if(!currentGeneration(value)){card.append(paragraph("Connection pending: the controller has not observed this generation, and its observation time is unavailable. This card refreshes automatically.","workspace-guidance attention"));return}
      const section=document.createElement("section");section.className="workspace-connect";
      const heading=document.createElement("h4");heading.textContent="Connect an agent client";section.append(heading);
      if(!Array.isArray(value.repositories)){section.append(paragraph("Repository binding was not included in this status response. Refresh after the Cloud service update.","workspace-guidance attention"));card.append(section);return}
      const repos=value.repositories;
      if(repos.length!==1){section.append(paragraph(repos.length===0?"Bind one repository before connecting a hosted client.":"MCP currently needs exactly one bound repository. Ask a workspace administrator to resolve this before connecting.","workspace-guidance attention"));card.append(section);return}
      if(!Array.isArray(mcp?.configured_clients)){section.append(paragraph("Client configuration was not included in this status response. Refresh after the Cloud service update.","workspace-guidance attention"));card.append(section);return}
      const clients=mcp.configured_clients.filter(id=>CLIENT_STEPS[id]);
      if(!clients.length){section.append(paragraph("No named client is configured in Vuoro Cloud. Ask the Vuoro operator to enable one.","workspace-guidance attention"));card.append(section);return}
      const url=document.createElement("code");url.textContent=mcp.resource||"MCP URL unavailable";
      const endpoint=paragraph("MCP URL: ");endpoint.append(url);section.append(endpoint);
      const scopes=paragraph("Server-supported MCP scopes: ");for(const [index,scope] of (mcp.scopes||[]).entries()){if(index)scopes.append(", ");const code=document.createElement("code");code.textContent=scope;scopes.append(code)}section.append(scopes);
      section.append(paragraph("These are server capabilities, not your current grant. Your tools also depend on your workspace role and consent. Viewers and read-only workspaces can only read. One grant covers one workspace; an old grant never widens on refresh.","workspace-guidance"));
      for(const id of clients){const guide=CLIENT_STEPS[id];const details=document.createElement("details");const summary=document.createElement("summary");summary.textContent=`Connect with ${guide.name}`;const steps=document.createElement("ol");for(const line of guide.steps){const item=document.createElement("li");item.textContent=line;steps.append(item)}details.append(summary,steps);section.append(details)}
      card.append(section);
    }
    async function dashboard() {
      track("dashboard_viewed","/dashboard");
      app.innerHTML = `<section><h2>Workspaces</h2><div id="dashboard-body">Loading…</div></section>`;
      const body = document.querySelector("#dashboard-body");
      let pollTimer = null;
      let shellBuilt = false;
      const stopPoll = () => { if (pollTimer) { clearInterval(pollTimer); pollTimer = null; } };
      const showSignIn = () => {
        stopPoll();
        app.innerHTML = `<section><h2>Sign in required</h2><p><a href="${API}/api/control/v1/auth/github/start?redirect_path=/dashboard">Sign in with GitHub</a></p><p>New users need an invitation at <a href="/join">/join</a>.</p></section>`;
      };
